Python<pre><code>def search(node, target):
    if node is None:
        return None

    if target == node.value:
        return node

    if target &lt; node.value:
        return search(node.left, target)

    return search(node.right, target)
</code></pre>

Python<pre><code>def insert(node, v):
    if node is None:
        return BSTNode(v)

    if v &lt; node.value:
        node.left = insert(node.left, v)
        node.left.parent = node

    elif v &gt; node.value:
        node.right = insert(node.right, v)
        node.right.parent = node

    else:
        node.count += 1

    return node
</code></pre>

Python<pre><code>def is_valid_bst(node, low=float("-inf"), high=float("inf")):
    if node is None:
        return True

    if not (low &lt; node.value &lt; high):
        return False

    return (
        is_valid_bst(node.left, low, node.value)
        and is_valid_bst(node.right, node.value, high)
    )
</code></pre>

Python<pre><code>def computeConnectivity(g):
    result = g.nb_vertices()
    gnew = copy.deepcopy(g)

    for k in range(result):
        for i in range(result):
            for j in range(result):
                if (
                    gnew.has_edge(i, k)
                    and gnew.has_edge(k, j)
                ):
                    gnew.add_edge(i, j)

    return gnew
</code></pre>

Python<pre><code>class Solution(object):
    def firstUniqChar(self, s):
        """
        :type s: str
        :rtype: int
        """
        memo={}
        for i,num in enumerate(s):
            if num in memo:
                memo[num].append(i)
            else:
                memo[num]=[i]

        for key in s:
            if len(memo[key])==1:
                return memo[key][0]
        return -1
